// === Tab: puppet ===
class PuppetPoint {
	constructor({ puppet, position, parent, orientAlongAxis = true, fixed = false }) {
		this.puppet = puppet
		this.position = position.copy()
		this.initialPosition = position.copy()
		this.parent = parent
		this.geometry = []
		this.children = {}
		this.orientAlongAxis = orientAlongAxis
		this.constraints = []
		this.fixed = fixed
	}

	addConstraint(constraint) {
		this.constraints.push(constraint)
	}

	constrain() {
		for (const constraint of this.constraints) {
			constraint()
		}
	}

	addChild(name, position, options = {}) {
		const child = new PuppetPoint({
			puppet: this.puppet,
			position,
			parent: this,
			...options,
		})
		this.puppet.points[name] = child
		this.children[name] = child
		return child
	}

	length() {
		if (!this.parent) return 0
		return this.initialPosition.mag()
	}

	rotate(angle, axis) {
		if (!this.parent) return this
		const vec = this.direction()
		const mat = new p5.Matrix()
		mat.rotate(angle, axis)
		const rotated = mat.multiplyDirection(vec)
		this.position = rotated.setMag(this.length())
		return this
	}

	absolutePosition() {
		let pos = createVector()
		let node = this
		let _wG_1 = 0; while ((node) && ++_wG_1 < 20000) {
			pos.add(node.position)
			node = node.parent
		}
		return pos
	}

	absoluteInitialPosition() {
		let pos = createVector()
		let node = this
		let _wG_2 = 0; while ((node) && ++_wG_2 < 20000) {
			pos.add(node.initialPosition)
			node = node.parent
		}
		return pos
	}

	localPosition(root) {
		let pos = createVector()
		let node = this
		let _wG_3 = 0; while ((node !== root) && ++_wG_3 < 20000) {
			pos.add(node.position)
			node = node.parent
		}
		return pos
	}

	reset() {
		this.position = this.initialPosition.copy()
		for (const key in this.children) {
			this.children[key].reset()
		}
	}

	direction() {
		return this.position.copy().normalize()
	}

	initialDirection() {
		return this.initialPosition.copy().normalize()
	}

	orient() {
		if (!this.parent) return
		const direction = this.direction()
		const initialDirection = this.initialDirection()


		if (direction.copy().sub(initialDirection).mag() > 1e-6) {
			const axis = initialDirection.cross(direction)
			const angle = acos(direction.dot(initialDirection))
			rotate(angle, axis)
		}

		if (this.orientAlongAxis) {
			const up = createVector(0, -1, 0)
			if (up.dot(initialDirection) < 1) {
				const axis = up.cross(initialDirection)
				const angle = acos(up.dot(initialDirection))
				rotate(angle, axis)
			}
		}
	}

	addGeometry(drawGeometry, { at = 1 } = {}) {
		this.geometry.push({
			at,
			drawGeometry,
		})
	}

	drawGeometry() {
		for (const { drawGeometry, at } of this.geometry) {
			push()
			if (!this.orientAlongAxis) {
				const pos = p5.Vector.lerp(createVector(), this.position, at)
				translate(pos.x, pos.y, pos.z)
			}
			this.orient()
			if (this.orientAlongAxis) {
				const pos = createVector(0, -1, 0).setMag(at * this.length())
				translate(pos.x, pos.y, pos.z)
			}
			drawGeometry()
			pop()
		}
	}

	draw() {
		this.drawGeometry()
		push()
		translate(this.position.x, this.position.y, this.position.z)
		for (const key in this.children) {
			this.children[key].draw()
		}
		pop()
	}
}

class Puppet {
	constructor() {
		this.points = {};
		this.points.root = new PuppetPoint({ puppet: this, position: createVector(0, 0, 0) })
	}

	constrain() {
		for (key in this.points) {
			this.points[key].constrain()
		}
	}

	root() {
		return this.points.root
	}

	reset() {
		this.root().reset()
	}

	draw() {
		this.root().draw()
	}

	ik(grab, targetPt, iterations = 1) {
		const chain = [grab]
		while (chain[chain.length-1].parent !== this.root()) {
			chain.push(chain[chain.length-1].parent)
		}

		for (let i = 0; i < iterations; i++) {
			for (const parent of chain) {
				if (parent.fixed) continue
				const grabPt = grab.absolutePosition()
				const pivot = parent.parent
				const pivotPt = pivot.absolutePosition()
				const toTarget = targetPt.copy().sub(pivotPt).normalize()
				const toGrab = grabPt.copy().sub(pivotPt).normalize()
				const axis = toGrab.cross(toTarget).normalize()
				const angle = acos(toTarget.dot(toGrab))
				parent.rotate(angle, axis)
			}
		}
	}
}

class Horse extends Puppet {
	constructor() {
		super()
		this.root().addChild('mid', createVector(0, -50, 100))
		this.points.mid.addChild('neckBase', createVector(0, 20, 100))
		this.points.neckBase.addChild('neckTip', createVector(0, -50, 20))
		this.points.neckTip.addChild('head', createVector(0, -40, 0))
		this.points.head.addChild('headTip', createVector(0, 40, 40))

		const capsule = (pt, r) => {
			pt.addGeometry(() => {
				cylinder(r, pt.length())
			}, { at: 0.5 })
			pt.addGeometry(() => {
				sphere(r)
			}, { at: 0 })
			pt.addGeometry(() => {
				sphere(r)
			}, { at: 1 })
		}

		let tail = this.root()
		for (let i = 0; i < 10; i++) {
			tail = tail.addChild(`tail${i}`, createVector(0, 0, -20))
			capsule(tail, map(i, 0, 9, 10, 1))
		}
		this.tailTip = tail

		const addLegs = (source, i) => {
			for (const { side, scaleX } of [{ side: 'L', scaleX: -1 }, { side: 'R', scaleX: 1 }]) {
				const hip = source.addChild(`hip${side}${i}`, createVector(scaleX*30, 5, 0), { fixed: true })
				const knee = hip.addChild(`knee${side}${i}`, createVector(0, 90, 10))
				const ankle = knee.addChild(`ankle${side}${i}`, createVector(0, 90, -10))
				const toe = ankle.addChild(`toe${side}${i}`, createVector(0, 50, 50))
				toe.addConstraint(() => {
					toe.position.y = 30 //constrain(toe.position.y, -20, 50)
					if (abs(toe.position.x) > 20) {
						toe.position.x = 20 * Math.sign(toe.position.x)
					}
					toe.position.setMag(toe.length())
				})
			}
		}

		addLegs(this.root(), 0)
		addLegs(this.points.mid, 1)
		addLegs(this.points.neckBase, 2)

		capsule(this.points.head, 15)
		capsule(this.points.headTip, 15)

		this.points.headTip.addGeometry(() => {
			for (const side of [-1, 1]) {
				push()
				fill(0)
				translate(side * 15, 0, -5)
				sphere(5)
				pop()
			}
		}, { at: 0.5 })
		this.points.headTip.addGeometry(() => {
			for (const side of [-1, 1]) {
				push()
				translate(side * 15, 0, -5)
				rotateX(PI/2)
				translate(0, -15, 0)
				rotateY(side * PI * 0.25)
				scale(1, 1, 0.2)
				cylinder(7, 30)
				pop()
			}
		}, { at: 0 })

		this.points.neckTip.addGeometry(() => {
			cylinder(15, this.points.neckTip.length())
		}, { at: 0.5 })

		this.points.neckBase.addGeometry(() => {
			for (const side of [-1, 1]) {
				push()
				translate(side*20, -30, 0)
				sphere(30)
				pop()
			}
		}, { at: 0.5 })
		capsule(this.points.neckBase, 30)
		capsule(this.points.mid, 35)
		this.points.mid.addGeometry(() => {
			sphere(45)
		}, { at: 0 })

		for (const side of ['L', 'R']) {
			for (let i = 0; i < 3; i++) {
				for (const [j, point] of ['knee', 'ankle', 'toe'].entries()) {
					capsule(this.points[`${point}${side}${i}`], map(j, 0, 2, 15, 10))
				}
			}
		}

		// for (key in this.points) {
